# Send validated config to deployment orchestrator for audit compliance
# Convert .env.test to JSON
env_to_json() {
  awk -F= '
    BEGIN { printf("{") }
    /^[[:space:]]*#/ { next }
    NF==0 { next }
    {
        key=$1; value=$2;
        # trim whitespace
        sub(/^\s+/, "", key); sub(/\s+$/,"", key);
        sub(/^\s+/, "", value); sub(/\s+$/,"", value);
        # escape backslashes and double quotes in value
        gsub(/\\/,"\\\\", value);
        gsub(/\"/,"\\\"", value);
        if (NR>1) printf(",")
        printf("\"%s\":\"%s\"", key, value)
    }
    END { printf("}\n") }
  ' .env.test
}

CONFIG_JSON=$(env_to_json)

# POST the config JSON
echo "Sending config to orchestrator..."
http_response=$(curl -s -o /dev/null -w "%{http_code}" -X POST -H "Content-Type: application/json" -d "$CONFIG_JSON" http://localhost:47301/api/deploy-config)
if [[ "$http_response" -ne 200 && "$http_response" -ne 201 ]]; then
  echo "Error: Failed to send config (HTTP $http_response)"
  exit 1
fi

